"""Write a write-once experiment plan after real inputs and model weights exist."""
import pathlib,json,hashlib,argparse,subprocess,importlib.metadata,sys
ROOT=pathlib.Path(__file__).resolve().parents[1]
def sha(p):return hashlib.file_digest(pathlib.Path(p).open('rb'),'sha256').hexdigest()
p=argparse.ArgumentParser();p.add_argument('--manifest',required=True);p.add_argument('--checkpoint',required=True);p.add_argument('--output',required=True);args=p.parse_args();manifest=pathlib.Path(args.manifest);ckpt=pathlib.Path(args.checkpoint);out=pathlib.Path(args.output)
assert not out.exists();spec=json.loads(manifest.read_text());receipt=json.loads(ckpt.with_suffix('.pth.download.json').read_text());assert receipt['state']=='completed' and sha(ckpt)==receipt['sha256']
