for p in [ROOT/'upstream/avism/avism_model.py',ROOT/'upstream/avism/modeling/transformer_decoder/avism.py',ROOT/'upstream/configs/avism/R50/avism_R50_IN.yaml',ROOT/'upstream/configs/avism/Base-AVIS.yaml']:files[str(p.relative_to(ROOT))]=sha(p)
inputs={}
for v in spec['videos']:
 for p in v['image_paths']+[v['audio_path']]:inputs[p]=sha(p)
plan={'study':spec.get('study','avis_dev_v1'),'claim':'Whether episodic audio-fusion normalization updates improve a fixed shortened AVISeg development panel beyond matched no-update views','cohort_selection':spec['selection'],'sampling_limitation':spec.get('sampling_limitation','fixed hash-selected development panel'),'source':'official AVISM R50 ImageNet; no retraining','manifest':str(manifest),'manifest_sha256':sha(manifest),'checkpoint':str(ckpt),'checkpoint_sha256':sha(ckpt),'checkpoint_derived':receipt.get('derived',False),'source_full_file_complete':receipt.get('source_full_file_complete',True),'input_hashes':inputs,'source_hashes':files,'critical_package_versions':critical_versions,'python_version':sys.version,'environment_policy':'no dependency installation or package change during the locked experiment','upstream_commit':subprocess.check_output(['git','-C',str(ROOT/'upstream'),'rev-parse','HEAD'],text=True).strip(),'arms':[{'method':'source','steps':0},{'method':'views','steps':0},{'method':'entropy','steps':3},{'method':'consistency','steps':3},{'method':'zero_features','steps':0},{'method':'cyclic_audio','steps':0}],'frozen_audio_controls':{'zero_features':'all-zero VGGish features through entire frozen frame and clip pipeline; not silence','cyclic_audio':'next video in locked cohort order modulo 8; donor positions floor(arange(target_T)*donor_T/target_T); no GT/category matching','interpretation':'diagnose prediction sensitivity and native performance; no invariance-to-shift => visual-bias causal inference'},'optimizer':{'name':'Adam','lr':1e-4,'weight_decay':0,'grad_clip_norm':1.0},'parameters':compat['audio_fusion_norm_parameters'],'parameter_count':6144,'seed':20261029,'episode_reset':'pretrained selected parameters before and after every video; fresh optimizer each video; model remains eval','views':['original cached frame queries + audio','joint reverse temporal order of cached frame queries and audio'],'matching':'detached Hungarian using class-distribution L1/2 + 1-mask-vector-cosine, fixed baseline query reference for training; no GT','readout':'source retains official single-view output; all other arms average matched class probabilities and matched clip mask vectors from two views, decoding through unchanged original-order frozen mask features','consistency_gate':{'fg_probability_min':0.3,'matched_class_equal':True,'matched_mask_cosine_min':0.9},'consistency_loss':'mean two-view class KL + matched mask-vector cosine distance (weight 1.0) to frozen matched baseline ensemble over gated queries + .01 parameter mean-square anchor','entropy_loss':'mean categorical entropy of original-view clip-query distributions including no-object','same_input_repeat_tolerance':1e-5,'video_count':len(spec['videos']),'frame_count':sum(v['length'] for v in spec['videos']),'crop':'entire original JPEG sequence, no truncation; fixed same eight convenience videos as short v3','parent_short_plan_sha256':spec['parent_short_plan_sha256'],'context_control':spec['context_control'],'metrics':['native official TrackMAP','native official HOTA','native official FSLA with native empty-mask convention and retained stratum counts','per-video runtime','peak allocated GPU memory','predicted track counts','parameter delta and unlabeled gate diagnostics'],'score_protocol':'seal every arm before opening GT in separate CPU scorer; nonfinite conditional stratum values are null with support counts, no replacement by zero','resource_ceiling':{'gpu':'one RTX5090; serial lease coordinated by parent','frames_per_video_max':max(v['length'] for v in spec['videos']),'video_count_max':8,'max_update_steps':3,'image_chunk':4,'selection_or_lr_sweep':False},'scope_boundary':'development feasibility only; no deployment adoption or generic novelty/causal reliability claim'}
out.parent.mkdir(parents=True,exist_ok=True);out.write_text(json.dumps(plan,indent=2));out.with_suffix(out.suffix+'.sha256').write_text(sha(out)+'  '+out.name+'\n');out.chmod(0o444);print(out,sha(out))
